  /// Seeds initial muscles, bindings, and exercises if tables are empty.
  static Future<void> populate(Database db) async {
    final muscleCountResult = await db.rawQuery('SELECT COUNT(*) as count FROM MUSCLE');
    final muscleCount = Sqflite.firstIntValue(muscleCountResult) ?? 0;
    if (muscleCount > 0) return; // Already seeded

    await db.transaction((txn) async {
      final batch = txn.batch();

      for (final m in muscles) {
        batch.insert('MUSCLE', m, conflictAlgorithm: ConflictAlgorithm.replace);
      }

      for (final b in meshBindings) {
        batch.insert('MUSCLE_MESH_BINDING', b, conflictAlgorithm: ConflictAlgorithm.replace);
      }

      for (final e in exercises) {
        batch.insert('EXERCISE', e, conflictAlgorithm: ConflictAlgorithm.replace);
      }

      for (final t in exerciseTargets) {
        batch.insert('EXERCISE_MUSCLE', t, conflictAlgorithm: ConflictAlgorithm.replace);
      }

      await batch.commit(noResult: true);
    });
  }
